const orderMachine = setup({
  types: {
    context: {} as { cid: string; payment: 'pending' | 'ok' },
    events: {} as { type: 'PAYMENT_OK' } | { type: 'TIMEOUT' },
  },
  guards: { paid: ({ context }) => context.payment === 'ok' },
  actors: { reserveStock: fromPromise(({ input }) => api.reserve(input)) },
}).createMachine({
  initial: 'awaitingPayment',
  states: {
    awaitingPayment: {
      after: { 3600000: { target: 'compensating' } },
      on: { PAYMENT_OK: { guard: 'paid', target: 'awaitingStock' } },
    },
    awaitingStock: { invoke: { src: 'reserveStock', onDone: 'done', onError: 'compensating' } },
    done: { type: 'final' },
    compensating: { entry: ({ context }) => api.release(context.cid) },
  },
});

const actor = createActor(orderMachine, { snapshot: await store.load(cid) }).start();

