export async function orderWorkflow(order: Order): Promise<void> {
  const { reserveCredit, takePayment, releaseCredit, ship } = proxyActivities<Activities>({
    startToCloseTimeout: '30 seconds',
    retry: { maximumAttempts: 5 },
  });
  await reserveCredit(order);
  const paid = await condition('payment', '1 hour', () => state.payment === 'ok');
  if (!paid) {
    await releaseCredit(order);                     // compensate
    throw ApplicationFailure.nonRetryable('payment timeout');
  }
  await ship(order);
}
